import java.util.*;

public class Main {
    public static int solver(int n, int m) {
        int first = 0, second = 0, copyN = n;
        int point = (m % 2 == 0) ? m : m + 1;

        while (copyN != point / 2) {
            if (copyN > point / 2) {
                first += copyN - (point / 2);
                copyN = point / 2;
            }
            if (copyN < point / 2) {
                copyN *= 2;
                first += 1;
            }
        }
        first += (m % 2 == 0) ? 1 : 2;

        copyN = n;
        while (copyN != m) {
            if (copyN < m) copyN *= 2;
            else {
                second += copyN - m;
                break;
            }
            second += 1;
        }

        return Math.min(first, second);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextLine()) return;
        String line = scanner.nextLine();
        scanner.close();

        String[] parts = line.split(" ");
        int n = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);

        if (n > m) {
            System.out.println(n - m);
            return;
        }

        Set<Integer> data = new HashSet<>();
        data.add(n);

        int find = 0;
        while (true) {
            Set<Integer> map = new HashSet<>();
            for (int x : data) {
                if (x - 1 >= 1) {
                    int nx = x - 1;
                    map.add(nx);
                    if (nx == m) {
                        System.out.println(find + 1);
                        return;
                    }
                }
                if (x * 2 <= m * 1.5) {
                    int nx = x * 2;
                    map.add(nx);
                    if (nx == m) {
                        System.out.println(find + 1);
                        return;
                    }
                }
            }
            data = map;
            find += 1;
        }
    }
}

